export type ClaveTraduccion = keyof typeof TRADUCCIONES

// Reemplaza {variables} en el texto — ej. t('inicio_hola', {nombre:'Felipe'})
// → "Hola, Felipe". También maneja el {s} de plural de forma simple: si
// la variable "n" es 1, {s} desaparece; si no, queda como "s".
export function t(clave: ClaveTraduccion, idioma: Idioma, vars?: Record<string, string | number>): string {
  let texto: string = TRADUCCIONES[clave]?.[idioma] ?? TRADUCCIONES[clave]?.es ?? clave
  if (vars) {
    if ('n' in vars) vars = { ...vars, s: Number(vars.n) === 1 ? '' : 's' }
    for (const [k, v] of Object.entries(vars)) {
      texto = texto.replaceAll(`{${k}}`, String(v))
    }
  }
  return texto
}
